import { identity, localToWorldPoint, worldToLocalPoint } from './math';
import type { Point2D, Transform2D } from './math';
import { createId, Rig } from './Rig';
import type { Bone, Layer } from './Rig';
import type { VectorShape } from './model';

/** The portions of a character that can be generated by {@link autoRig}. */
export type AutoRigMode = 'full' | 'upper' | 'lower' | 'head';

export interface AutoRigOptions {
  mode: AutoRigMode;
  spineCount: number;
  createHeadControls: boolean;
  bindArtwork: boolean;
  gearUp: boolean;
}

/** A stable, JSON-safe description of an auto-rigging pass. */
export interface AutoRigReport {
  mode: AutoRigMode;
  spineCount: number;
  createdBoneIds: string[];
  reusedBoneIds: string[];
  boundLayerIds: string[];
  newlyBoundLayerIds: string[];
  unmappedLayerIds: string[];
  warnings: string[];
  semanticBones: Record<string, string>;
  controlLayerIds: string[];
  boneCount: number;
  layerCount: number;
  /** Friendly aliases retained for consumers that prefer shorter report names. */
  createdBones: string[];
  reusedBones: string[];
  boundLayers: string[];
  unmappedLayers: string[];
}

export interface GearUpReport {
  normalizedLayers: number;
  repairedTransforms: number;
  repairedOpacity: number;
  warnings: string[];
}

export interface CircleJointOptions {
  name?: string;
  radius?: number;
  radiusX?: number;
  radiusY?: number;
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  /** A joint is the bone origin; a tip is its visible end. */
  at?: 'joint' | 'tip';
  /** Alias for `at`, useful when the call is driven by serialized options. */
  point?: 'joint' | 'tip';
}

const DEFAULT_AUTO_RIG_OPTIONS: AutoRigOptions = {
  mode: 'full',
  spineCount: 3,
  createHeadControls: false,
  bindArtwork: true,
  gearUp: true,
};

const SEMANTIC_BONES_KEY = 'autoRig.semanticBones';
const CONTROL_LAYERS_KEY = 'autoRig.controlLayers';
const GENERATED_LAYERS_KEY = 'autoRig.generatedLayerIds';
const MAX_SPINE_COUNT = 16;
const EPSILON = 1e-6;

type Bounds = { minX: number; minY: number; maxX: number; maxY: number };
type BoneKey = string;

interface SkeletonPoint {
  start: Point2D;
  end: Point2D;
  parent?: BoneKey;
}

interface EnsureResult {
  id: string;
  created: boolean;
}

interface NamedLayerMatch {
  key: BoneKey;
  confidence: 'name' | 'bounds';
}

function finite(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function finitePoint(point: Point2D | undefined | null): point is Point2D {
  return Boolean(point) && Number.isFinite(point!.x) && Number.isFinite(point!.y);
}

function safeTransform(value: Partial<Transform2D> | undefined, fallback: Transform2D = identity()): Transform2D {
  return {
    x: finite(value?.x, fallback.x),
    y: finite(value?.y, fallback.y),
    rotation: finite(value?.rotation, fallback.rotation),
    scaleX: Number.isFinite(value?.scaleX) && Math.abs(value!.scaleX!) > EPSILON ? Math.abs(value!.scaleX!) : fallback.scaleX,
    scaleY: Number.isFinite(value?.scaleY) && Math.abs(value!.scaleY!) > EPSILON ? Math.abs(value!.scaleY!) : fallback.scaleY,
  };
}

function normalizeText(value: unknown): string {
  return String(value ?? '').trim().toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}

function words(value: unknown): string[] {
  return normalizeText(value).split(' ').filter(Boolean);
}

function hasAny(value: string, candidates: string[]): boolean {
  return candidates.some(candidate => value.includes(candidate));
}

function readObjectMap(rig: Rig, key: string): Record<string, string> {
  try {
    const parsed: unknown = JSON.parse(rig.metadata[key] ?? '{}');
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    return Object.entries(parsed as Record<string, unknown>).reduce<Record<string, string>>((result, [name, id]) => {
      if (typeof id === 'string' && id) result[name] = id;
      return result;
    }, {});
  } catch {
    return {};
  }
}

function readIdList(rig: Rig, key: string): string[] {
  try {
    const parsed: unknown = JSON.parse(rig.metadata[key] ?? '[]');
    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string' && id.length > 0) : [];
  } catch {
    return [];
  }
}

function writeObjectMap(rig: Rig, key: string, value: Record<string, string>): void {
  rig.metadata[key] = JSON.stringify(value);
}

function writeIdList(rig: Rig, key: string, value: Iterable<string>): void {
  rig.metadata[key] = JSON.stringify([...new Set(value)].sort());
}

function clamp01(value: unknown, fallback = 1): number {
  const normalized = finite(value, fallback);
  return Math.min(1, Math.max(0, normalized));
}

/**
 * Normalize user-facing auto-rig options. Invalid values fall back to a
 * complete, bindable rig and the spine count is kept deliberately bounded so
 * malformed projects cannot create an unbounded number of bones.
 */
export function normalizeAutoRigOptions(options: Partial<AutoRigOptions> | null | undefined = {}): AutoRigOptions {
  const source = options && typeof options === 'object' ? options : {};
  const mode: AutoRigMode = source.mode === 'upper' || source.mode === 'lower' || source.mode === 'head'
    ? source.mode
    : 'full';
  const requestedCount = Number.isFinite(source.spineCount) ? Math.floor(source.spineCount as number) : DEFAULT_AUTO_RIG_OPTIONS.spineCount;
  return {
    mode,
    spineCount: Math.min(MAX_SPINE_COUNT, Math.max(1, requestedCount)),
    createHeadControls: typeof source.createHeadControls === 'boolean' ? source.createHeadControls : DEFAULT_AUTO_RIG_OPTIONS.createHeadControls,
    bindArtwork: typeof source.bindArtwork === 'boolean' ? source.bindArtwork : DEFAULT_AUTO_RIG_OPTIONS.bindArtwork,
    gearUp: typeof source.gearUp === 'boolean' ? source.gearUp : DEFAULT_AUTO_RIG_OPTIONS.gearUp,
  };
}

/**
 * Repair only unsafe presentation channels on artwork. Positions, geometry,
 * meshes, IDs and binding records are intentionally left alone.
 */
export function gearUpArtwork(rig: Rig): GearUpReport {
  const report: GearUpReport = { normalizedLayers: 0, repairedTransforms: 0, repairedOpacity: 0, warnings: [] };
  if (!rig || !rig.layers) return report;

  rig.layers.forEach((layer) => {
    const previous = layer.local;
    const next = safeTransform(previous, identity());
    const changedTransform = !previous || Object.keys(next).some((key) => next[key as keyof Transform2D] !== previous[key as keyof Transform2D]);
    if (changedTransform) {
      // Keep authored x/y exactly when finite. Non-finite positions have no
      // meaningful canvas location, so zero is the only safe finite fallback.
      next.x = Number.isFinite(previous?.x) ? previous!.x : 0;
      next.y = Number.isFinite(previous?.y) ? previous!.y : 0;
      layer.local = next;
      report.repairedTransforms += 1;
    }
    const previousOpacity = layer.opacity;
    const opacity = clamp01(previousOpacity, 1);
    if (opacity !== previousOpacity) {
      layer.opacity = opacity;
      report.repairedOpacity += 1;
    }
    if (changedTransform || opacity !== previousOpacity) report.normalizedLayers += 1;
  });
  // `update` derives world transforms without changing artwork geometry or
  // bindings that still point at valid IDs.
  rig.update();
  return report;
}

function shapePoints(shape: VectorShape): Point2D[] {
  if (shape.kind === 'ellipse') {
    const x = finite(shape.x, 0), y = finite(shape.y, 0);
    const rx = Math.abs(finite(shape.radiusX, 1)), ry = Math.abs(finite(shape.radiusY, 1));
    return [{ x: x - rx, y: y - ry }, { x: x + rx, y: y + ry }];
  }
  if (shape.kind === 'polygon') return (shape.points ?? []).filter(finitePoint);
  if (shape.kind === 'rect') {
    const x = finite(shape.x, 0), y = finite(shape.y, 0), width = finite(shape.width, 0), height = finite(shape.height, 0);
    return [{ x, y }, { x: x + width, y: y + height }];
  }
  if (shape.kind === 'path') {
    const numbers = (shape.d ?? '').match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi)?.map(Number) ?? [];
    const points: Point2D[] = [];
    for (let index = 0; index + 1 < numbers.length; index += 2) {
      if (Number.isFinite(numbers[index]) && Number.isFinite(numbers[index + 1])) points.push({ x: numbers[index], y: numbers[index + 1] });
    }
    return points;
  }
  return [];
}

function layerLocalBounds(layer: Layer): Bounds {
  if (layer.type === 'image') {
    const width = Math.abs(finite(layer.width, 110)), height = Math.abs(finite(layer.height, 140));
    return { minX: -width / 2, minY: -height / 2, maxX: width / 2, maxY: height / 2 };
  }
  const points = layer.shapes.flatMap(shapePoints);
  if (!points.length) return { minX: -1, minY: -1, maxX: 1, maxY: 1 };
  return {
    minX: Math.min(...points.map(point => point.x)),
    minY: Math.min(...points.map(point => point.y)),
    maxX: Math.max(...points.map(point => point.x)),
    maxY: Math.max(...points.map(point => point.y)),
  };
}

function worldBounds(rig: Rig, layer: Layer): Bounds {
  const transform = safeTransform(layer.world, safeTransform(layer.local));
  const local = layerLocalBounds(layer);
  const points = [
    { x: local.minX, y: local.minY }, { x: local.maxX, y: local.minY },
    { x: local.maxX, y: local.maxY }, { x: local.minX, y: local.maxY },
  ].map(point => localToWorldPoint(transform, point));
  if (!points.every(finitePoint)) {
    const x = finite(layer.local?.x, finite(rig.canvas.width, 800) / 2);
    const y = finite(layer.local?.y, finite(rig.canvas.height, 520) / 2);
    return { minX: x, minY: y, maxX: x, maxY: y };
  }
  return {
    minX: Math.min(...points.map(point => point.x)),
    minY: Math.min(...points.map(point => point.y)),
    maxX: Math.max(...points.map(point => point.x)),
    maxY: Math.max(...points.map(point => point.y)),
  };
}

function unionBounds(bounds: Bounds[]): Bounds | null {
  if (!bounds.length) return null;
  return {
    minX: Math.min(...bounds.map(item => item.minX)),
    minY: Math.min(...bounds.map(item => item.minY)),
    maxX: Math.max(...bounds.map(item => item.maxX)),
    maxY: Math.max(...bounds.map(item => item.maxY)),
  };
}

function canvasBounds(rig: Rig): Bounds {
  const width = Math.max(1, finite(rig.canvas?.width, 800));
  const height = Math.max(1, finite(rig.canvas?.height, 520));
  return { minX: 0, minY: 0, maxX: width, maxY: height };
}

function midpoint(bounds: Bounds): Point2D {
  return { x: (bounds.minX + bounds.maxX) / 2, y: (bounds.minY + bounds.maxY) / 2 };
}

function expandBounds(bounds: Bounds, padding: number): Bounds {
  return { minX: bounds.minX - padding, minY: bounds.minY - padding, maxX: bounds.maxX + padding, maxY: bounds.maxY + padding };
}

function pointInBounds(point: Point2D, bounds: Bounds): boolean {
  return point.x >= bounds.minX && point.x <= bounds.maxX && point.y >= bounds.minY && point.y <= bounds.maxY;
}

function setBoneWorldPose(rig: Rig, boneId: string, start: Point2D, end: Point2D): boolean {
  const bone = rig.bones.get(boneId);
  if (!bone || !finitePoint(start) || !finitePoint(end)) return false;
  const parent = bone.parentId && bone.parentId !== bone.id ? rig.bones.get(bone.parentId) : undefined;
  const localStart = parent ? worldToLocalPoint(parent.world, start) : start;
  if (!localStart) return false;
  const length = Math.max(EPSILON, Math.hypot(end.x - start.x, end.y - start.y));
  const worldRotation = Math.atan2(end.y - start.y, end.x - start.x);
  const parentRotation = parent?.world.rotation ?? 0;
  const rotation = worldRotation - parentRotation;
  if (![localStart.x, localStart.y, rotation, length].every(Number.isFinite)) return false;
  bone.local = { ...bone.local, x: localStart.x, y: localStart.y, rotation, scaleX: 1, scaleY: 1 };
  bone.length = length;
  rig.update();
  return true;
}

function findSemanticBone(rig: Rig, semantic: BoneKey, names: Record<string, string>): string | undefined {
  const mapped = names[semantic];
  if (mapped && rig.bones.has(mapped)) return mapped;
  const displayNames: Record<string, string> = {
    root: 'Root', hips: 'Hips', head: 'Head', headController: 'Head control',
    eyebrowL: 'Eyebrow L', eyebrowR: 'Eyebrow R', pupilL: 'Pupil L', pupilR: 'Pupil R',
    leftUpperArm: 'Left upper arm', leftLowerArm: 'Left lower arm', leftHand: 'Left hand',
    rightUpperArm: 'Right upper arm', rightLowerArm: 'Right lower arm', rightHand: 'Right hand',
    leftUpperLeg: 'Left upper leg', leftLowerLeg: 'Left lower leg', leftFoot: 'Left foot',
    rightUpperLeg: 'Right upper leg', rightLowerLeg: 'Right lower leg', rightFoot: 'Right foot',
  };
  const spine = semantic.match(/^spine(\d+)$/);
  const expected = normalizeText(displayNames[semantic] ?? (spine ? `Spine ${spine[1]}` : semantic));
  return [...rig.bones.values()].find((bone) => normalizeText(bone.name) === expected)?.id;
}

function ensureBone(
  rig: Rig,
  semantic: BoneKey,
  name: string,
  parentId: string | null,
  point: SkeletonPoint,
  semanticBones: Record<string, string>,
  createdBoneIds: string[],
  reusedBoneIds: string[],
): EnsureResult {
  let id = findSemanticBone(rig, semantic, semanticBones);
  let created = false;
  if (!id) {
    id = rig.addBone(parentId, name, Math.max(EPSILON, Math.hypot(point.end.x - point.start.x, point.end.y - point.start.y)));
    created = true;
    createdBoneIds.push(id);
  } else {
    reusedBoneIds.push(id);
    const bone = rig.bones.get(id);
    if (bone && bone.parentId !== parentId) rig.reparentBone(id, parentId, true);
  }
  semanticBones[semantic] = id;
  rig.update();
  const bone = rig.bones.get(id);
  if (bone && (created || !Number.isFinite(bone.length) || !Number.isFinite(bone.local.x) || !Number.isFinite(bone.local.y))) {
    setBoneWorldPose(rig, id, point.start, point.end);
  } else if (bone) {
    // A reused semantic bone keeps its authored pose, while malformed channels
    // are always repaired before subsequent bindings read its world transform.
    bone.local = safeTransform(bone.local, identity());
    rig.update();
  }
  return { id, created };
}

function skeletonPoints(mode: AutoRigMode, spineCount: number, bounds: Bounds): Map<BoneKey, { name: string; point: SkeletonPoint }> {
  const result = new Map<BoneKey, { name: string; point: SkeletonPoint }>();
  const center = midpoint(bounds);
  const height = Math.max(160, bounds.maxY - bounds.minY || 260);
  const width = Math.max(140, bounds.maxX - bounds.minX || 180);
  const top = Math.min(bounds.minY, center.y - height / 2);
  const bottom = Math.max(bounds.maxY, center.y + height / 2);
  const bodyHeight = Math.max(120, bottom - top);
  const hipY = top + bodyHeight * 0.58;
  const shoulderY = top + bodyHeight * 0.30;
  const hipWidth = Math.max(18, width * 0.12);
  const shoulderWidth = Math.max(24, width * 0.25);
  const add = (key: BoneKey, name: string, start: Point2D, end: Point2D, parent?: BoneKey) => result.set(key, { name, point: { start, end, parent } });

  if (mode !== 'head') {
    add('root', 'Root', { x: center.x, y: hipY }, { x: center.x + 1, y: hipY });
    add('hips', 'Hips', { x: center.x, y: hipY }, { x: center.x + 1, y: hipY }, 'root');
  }
  if (mode === 'full' || mode === 'upper') {
    const step = Math.max(12, (hipY - shoulderY) / spineCount);
    for (let index = 0; index < spineCount; index += 1) {
      const start = { x: center.x, y: hipY - step * index };
      const end = { x: center.x, y: hipY - step * (index + 1) };
      add(`spine${index + 1}`, `Spine ${index + 1}`, start, end, index ? `spine${index}` : 'hips');
    }
    const chest = `spine${spineCount}`;
    add('head', 'Head', { x: center.x, y: shoulderY }, { x: center.x, y: top - bodyHeight * 0.04 }, chest);
    for (const side of [-1, 1] as const) {
      const label = side < 0 ? 'Left' : 'Right';
      const prefix = side < 0 ? 'left' : 'right';
      const shoulder = { x: center.x + side * shoulderWidth, y: shoulderY + bodyHeight * 0.03 };
      const elbow = { x: center.x + side * width * 0.38, y: shoulderY + bodyHeight * 0.18 };
      const wrist = { x: center.x + side * width * 0.50, y: shoulderY + bodyHeight * 0.34 };
      const hand = { x: center.x + side * width * 0.54, y: shoulderY + bodyHeight * 0.39 };
      add(`${prefix}UpperArm`, `${label} upper arm`, shoulder, elbow, chest);
      add(`${prefix}LowerArm`, `${label} lower arm`, elbow, wrist, `${prefix}UpperArm`);
      add(`${prefix}Hand`, `${label} hand`, wrist, hand, `${prefix}LowerArm`);
    }
  }
  if (mode === 'full' || mode === 'lower') {
    for (const side of [-1, 1] as const) {
      const label = side < 0 ? 'Left' : 'Right';
      const prefix = side < 0 ? 'left' : 'right';
      const hip = { x: center.x + side * hipWidth, y: hipY };
      const knee = { x: center.x + side * width * 0.16, y: hipY + bodyHeight * 0.25 };
      const ankle = { x: center.x + side * width * 0.18, y: hipY + bodyHeight * 0.50 };
      const foot = { x: center.x + side * width * 0.28, y: ankle.y + bodyHeight * 0.03 };
      add(`${prefix}UpperLeg`, `${label} upper leg`, hip, knee, 'hips');
      add(`${prefix}LowerLeg`, `${label} lower leg`, knee, ankle, `${prefix}UpperLeg`);
      add(`${prefix}Foot`, `${label} foot`, ankle, foot, `${prefix}LowerLeg`);
    }
  }
  if (mode === 'head') add('head', 'Head', { x: center.x, y: center.y + bodyHeight * 0.16 }, { x: center.x, y: center.y - bodyHeight * 0.20 });
  return result;
}

function generatedLayerSet(rig: Rig): Set<string> {
  const ids = new Set(readIdList(rig, GENERATED_LAYERS_KEY));
  rig.layers.forEach((layer) => {
    const name = normalizeText(layer.name);
    if (name.startsWith('autorig') || name.startsWith('auto rig')) ids.add(layer.id);
  });
  return ids;
}

function currentBinding(rig: Rig, layerId: string): { boneId: string } | undefined {
  return [...rig.bindings.values()].find(binding => (binding.layerId ?? binding.imageId) === layerId);
}

function sideOf(name: string, centerX: number, layerX: number): 'left' | 'right' | undefined {
  const tokens = new Set(words(name));
  if (tokens.has('left') || tokens.has('l')) return 'left';
  if (tokens.has('right') || tokens.has('r')) return 'right';
  if (Number.isFinite(layerX) && Math.abs(layerX - centerX) > 12) return layerX < centerX ? 'left' : 'right';
  return undefined;
}

function namedLayerMatch(layer: Layer, bounds: Bounds, centerX: number): NamedLayerMatch | undefined {
  const name = normalizeText(layer.name);
  const x = (bounds.minX + bounds.maxX) / 2;
  const side = sideOf(name, centerX, x);
  if (hasAny(name, ['eyebrow', 'brow'])) {
    return side ? { key: side === 'left' ? 'eyebrowL' : 'eyebrowR', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['pupil', 'iris', 'eye'])) {
    return side ? { key: side === 'left' ? 'pupilL' : 'pupilR', confidence: 'name' } : { key: 'head', confidence: 'name' };
  }
  if (hasAny(name, ['head', 'face', 'skull', 'helmet', 'hair'])) return { key: 'head', confidence: 'name' };
  if (hasAny(name, ['hand', 'glove', 'fist', 'wrist'])) {
    return side ? { key: side === 'left' ? 'leftHand' : 'rightHand', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['forearm', 'lower arm', 'elbow'])) {
    return side ? { key: side === 'left' ? 'leftLowerArm' : 'rightLowerArm', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['upper arm', 'arm', 'sleeve', 'shoulder'])) {
    return side ? { key: side === 'left' ? 'leftUpperArm' : 'rightUpperArm', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['foot', 'feet', 'boot', 'shoe'])) {
    return side ? { key: side === 'left' ? 'leftFoot' : 'rightFoot', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['shin', 'calf', 'lower leg', 'ankle'])) {
    return side ? { key: side === 'left' ? 'leftLowerLeg' : 'rightLowerLeg', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['thigh', 'upper leg', 'leg', 'knee'])) {
    return side ? { key: side === 'left' ? 'leftUpperLeg' : 'rightUpperLeg', confidence: 'name' } : undefined;
  }
  if (hasAny(name, ['pelvis', 'hip', 'hips'])) return { key: 'hips', confidence: 'name' };
  if (hasAny(name, ['torso', 'chest', 'spine', 'body', 'jacket', 'shirt', 'shirt', 'trunk'])) return { key: 'spineLast', confidence: 'name' };
  return undefined;
}

function distanceToSegment(point: Point2D, start: Point2D, end: Point2D): number {
  const dx = end.x - start.x, dy = end.y - start.y;
  const lengthSquared = dx * dx + dy * dy;
  if (!Number.isFinite(lengthSquared) || lengthSquared <= EPSILON) return Math.hypot(point.x - start.x, point.y - start.y);
  const t = Math.max(0, Math.min(1, ((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSquared));
  return Math.hypot(point.x - (start.x + t * dx), point.y - (start.y + t * dy));
}

function fallbackBoneKey(
  rig: Rig,
  layer: Layer,
  bounds: Bounds,
  skeleton: Map<BoneKey, { name: string; point: SkeletonPoint }>,
  boneIds: Record<string, string>,
): BoneKey | undefined {
  const center = midpoint(bounds);
  const size = Math.max(bounds.maxX - bounds.minX, bounds.maxY - bounds.minY, 1);
  const candidates = [...skeleton.entries()].filter(([key]) => key !== 'root' && !key.toLowerCase().includes('control'))
    .flatMap(([key]) => {
      const bone = rig.bones.get(boneIds[key] ?? '');
      const end = bone ? rig.getBoneEnd(bone.id) : null;
      if (!bone || !end || !finitePoint(bone.world)) return [];
      return [{ key, distance: distanceToSegment(center, bone.world, end) }];
    }).sort((a, b) => a.distance - b.distance || a.key.localeCompare(b.key));
  if (!candidates.length || !pointInBounds(center, expandBounds(canvasBounds(rig), Math.max(32, size)))) return undefined;
  const nearest = candidates[0];
  const second = candidates[1];
  const threshold = Math.max(30, size * 0.85);
  if (nearest.distance > threshold) return undefined;
  if (second && nearest.distance > 12 && second.distance - nearest.distance < Math.max(8, nearest.distance * 0.15)) return undefined;
  return nearest.key;
}

/**
 * Remove every rigid or mesh artwork assignment while retaining the complete
 * bone hierarchy. The return value is the number of layers detached.
 */
export function resetJointAssignments(rig: Rig): number {
  if (!rig) return 0;
  let detached = 0;
  [...rig.layers.keys()].forEach((layerId) => {
    const hadBinding = Boolean(currentBinding(rig, layerId)) || Boolean(rig.layers.get(layerId)?.boundBoneId);
    const result = rig.unbind(layerId);
    if (hadBinding || result) detached += 1;
  });
  rig.bindings.forEach((binding, key) => {
    const layerId = binding.layerId ?? binding.imageId;
    if (layerId && rig.layers.has(layerId)) rig.bindings.delete(key);
  });
  rig.layers.forEach(layer => { layer.boundBoneId = null; });
  rig.update();
  return detached;
}

/**
 * Rename existing layers to useful semantic names without changing their IDs,
 * transforms, geometry, meshes, visibility or assignments. A supplied map is
 * applied first and is ignored for unknown IDs.
 */
export function renameLayersForRig(rig: Rig, requestedNames: Record<string, string> = {}): Record<string, string> {
  const renamed: Record<string, string> = {};
  const used = new Set<string>();
  rig.layers.forEach(layer => used.add(normalizeText(layer.name)));
  Object.entries(requestedNames).forEach(([id, name]) => {
    const layer = rig.layers.get(id);
    const next = typeof name === 'string' ? name.trim().slice(0, 256) : '';
    if (!layer || !next) return;
    if (layer.name !== next) { layer.name = next; renamed[id] = next; }
  });
  let index = 1;
  rig.layers.forEach(layer => {
    if (Object.prototype.hasOwnProperty.call(requestedNames, layer.id)) return;
    const normalizedLayerName = normalizeText(layer.name);
    if (normalizedLayerName.startsWith('autorig') || normalizedLayerName.startsWith('auto rig')) return;
    const current = normalizeText(layer.name);
    let next: string | undefined;
    if (hasAny(current, ['eyebrow', 'brow'])) next = sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Eyebrow L' : 'Eyebrow R';
    else if (hasAny(current, ['pupil', 'iris'])) next = sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Pupil L' : 'Pupil R';
    else if (hasAny(current, ['head', 'face', 'skull', 'helmet', 'hair'])) next = 'Head';
    else if (hasAny(current, ['torso', 'chest', 'body', 'jacket', 'shirt'])) next = 'Torso';
    else if (hasAny(current, ['hand', 'glove', 'fist'])) next = `${sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Left' : 'Right'} hand`;
    else if (hasAny(current, ['arm', 'sleeve', 'forearm'])) next = `${sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Left' : 'Right'} arm`;
    else if (hasAny(current, ['foot', 'boot', 'shoe'])) next = `${sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Left' : 'Right'} foot`;
    else if (hasAny(current, ['leg', 'thigh', 'shin', 'calf'])) next = `${sideOf(current, finite(rig.canvas.width, 800) / 2, finite(layer.local.x, 0)) === 'left' ? 'Left' : 'Right'} leg`;
    else next = `${layer.type === 'vector' ? 'Artwork' : 'Image'} ${index}`;
    index += 1;
    if (next && normalizeText(next) !== current) {
      const candidate = next;
      if (!used.has(normalizeText(candidate)) || normalizeText(candidate) === current) {
        layer.name = candidate;
        used.add(normalizeText(candidate));
        renamed[layer.id] = candidate;
      }
    }
  });
  return renamed;
}

/** Create a visible vector ellipse at a bone joint or tip and bind it. */
export function createCircleJoint(rig: Rig, boneId: string, options: CircleJointOptions | string | number = {}, radiusOverride?: number): string | null {
  const bone = rig?.bones.get(boneId);
  if (!bone) return null;
  rig.update();
  const opts: CircleJointOptions = typeof options === 'string'
    ? { name: options, ...(Number.isFinite(radiusOverride) ? { radius: radiusOverride } : {}) }
    : typeof options === 'number' ? { radius: options } : options ?? {};
  const radius = Number.isFinite(opts.radius) && Math.abs(opts.radius!) > EPSILON ? Math.abs(opts.radius!) : 8;
  const radiusX = Number.isFinite(opts.radiusX) && Math.abs(opts.radiusX!) > EPSILON ? Math.abs(opts.radiusX!) : radius;
  const radiusY = Number.isFinite(opts.radiusY) && Math.abs(opts.radiusY!) > EPSILON ? Math.abs(opts.radiusY!) : radius;
  const target = opts.at === 'joint' || opts.point === 'joint' ? bone.world : rig.getBoneEnd(boneId);
  if (!target || !finitePoint(target) || ![radiusX, radiusY].every(Number.isFinite)) return null;
  const shape: VectorShape = {
    id: createId('shape'), kind: 'ellipse', x: 0, y: 0, radiusX, radiusY,
    fill: typeof opts.fill === 'string' ? opts.fill : '#f59e0b',
    stroke: typeof opts.stroke === 'string' ? opts.stroke : '#fff7ed',
    strokeWidth: Number.isFinite(opts.strokeWidth) ? Math.max(0, opts.strokeWidth!) : 2,
  };
  const layerId = rig.addVectorLayer(opts.name?.trim() || `${bone.name} joint`, [shape]);
  const layer = rig.layers.get(layerId);
  if (!layer) return null;
  layer.visible = true;
  layer.local = { ...identity(), x: target.x, y: target.y };
  rig.update();
  if (!rig.bind(layerId, boneId)) {
    rig.remove(layerId);
    return null;
  }
  return layerId;
}

function ensureControlLayer(
  rig: Rig,
  semantic: BoneKey,
  boneId: string,
  name: string,
  radius: number,
  controlLayers: Record<string, string>,
  generatedLayerIds: Set<string>,
  report: AutoRigReport,
): void {
  const known = controlLayers[semantic];
  if (known && rig.layers.has(known)) {
    generatedLayerIds.add(known);
    report.controlLayerIds.push(known);
    return;
  }
  const id = createCircleJoint(rig, boneId, { name, radius });
  if (!id) {
    report.warnings.push(`Could not create visible control joint for ${name}.`);
    return;
  }
  controlLayers[semantic] = id;
  generatedLayerIds.add(id);
  report.controlLayerIds.push(id);
}

/**
 * Build a deterministic, artwork-aware skeleton. Existing semantic bones are
 * reused through IDs stored in project metadata, so running this repeatedly is
 * idempotent and never creates a second arm, leg or spine chain.
 */
export function autoRig(rig: Rig, options: Partial<AutoRigOptions> | null | undefined = {}): AutoRigReport {
  const normalized = normalizeAutoRigOptions(options);
  if (!rig) {
    const empty: AutoRigReport = {
      mode: normalized.mode, spineCount: normalized.spineCount, createdBoneIds: [], reusedBoneIds: [],
      boundLayerIds: [], newlyBoundLayerIds: [], unmappedLayerIds: [], warnings: ['A Rig instance is required.'],
      semanticBones: {}, controlLayerIds: [], boneCount: 0, layerCount: 0,
      createdBones: [], reusedBones: [], boundLayers: [], unmappedLayers: [],
    };
    return empty;
  }

  if (normalized.gearUp) gearUpArtwork(rig);
  rig.update();
  const generatedBefore = generatedLayerSet(rig);
  const artworkBounds = unionBounds([...rig.layers.values()].filter(layer => !generatedBefore.has(layer.id)).map(layer => worldBounds(rig, layer)));
  const bounds = artworkBounds ?? canvasBounds(rig);
  const semanticBones = readObjectMap(rig, SEMANTIC_BONES_KEY);
  const createdBoneIds: string[] = [];
  const reusedBoneIds: string[] = [];
  const skeleton = skeletonPoints(normalized.mode, normalized.spineCount, bounds);
  const resolved: Record<string, string> = {};
  const report: AutoRigReport = {
    mode: normalized.mode, spineCount: normalized.spineCount, createdBoneIds, reusedBoneIds,
    boundLayerIds: [], newlyBoundLayerIds: [], unmappedLayerIds: [], warnings: [], semanticBones,
    controlLayerIds: [], boneCount: 0, layerCount: 0,
    createdBones: createdBoneIds, reusedBones: reusedBoneIds, boundLayers: [], unmappedLayers: [],
  };

  // Resolve parent-first so every addBone call uses the native hierarchy API.
  const pending = new Set(skeleton.keys());
  while (pending.size) {
    let progressed = false;
    [...pending].forEach((key) => {
      const descriptor = skeleton.get(key)!;
      const parentId = descriptor.point.parent ? resolved[descriptor.point.parent] ?? findSemanticBone(rig, descriptor.point.parent, semanticBones) ?? null : null;
      if (descriptor.point.parent && !parentId) return;
      const result = ensureBone(rig, key, descriptor.name, parentId, descriptor.point, semanticBones, createdBoneIds, reusedBoneIds);
      resolved[key] = result.id;
      pending.delete(key);
      progressed = true;
    });
    if (!progressed) {
      report.warnings.push('Some semantic bones could not be connected to their requested parent.');
      break;
    }
  }
  // Torso artwork targets the last spine segment without making that display
  // name part of the public semantic vocabulary.
  if (resolved[`spine${normalized.spineCount}`]) resolved.spineLast = resolved[`spine${normalized.spineCount}`];
  writeObjectMap(rig, SEMANTIC_BONES_KEY, semanticBones);
  rig.update();

  if (normalized.createHeadControls && resolved.head) {
    const head = rig.bones.get(resolved.head);
    if (head && finitePoint(head.world)) {
      const headTip = rig.getBoneEnd(head.id) ?? head.world;
      const headLength = Math.max(20, finite(head.length, 60));
      const controlDescriptors: Array<[BoneKey, string, Point2D, Point2D, number]> = [
        ['headController', 'Head control', headTip, { x: headTip.x, y: headTip.y - headLength * 0.35 }, 11],
        ['eyebrowL', 'Eyebrow L', { x: head.world.x - headLength * 0.35, y: head.world.y - headLength * 0.55 }, { x: head.world.x - headLength * 0.35 + 1, y: head.world.y - headLength * 0.55 }, 6],
        ['eyebrowR', 'Eyebrow R', { x: head.world.x + headLength * 0.35, y: head.world.y - headLength * 0.55 }, { x: head.world.x + headLength * 0.35 + 1, y: head.world.y - headLength * 0.55 }, 6],
        ['pupilL', 'Pupil L', { x: head.world.x - headLength * 0.22, y: head.world.y - headLength * 0.25 }, { x: head.world.x - headLength * 0.22 + 1, y: head.world.y - headLength * 0.25 }, 5],
        ['pupilR', 'Pupil R', { x: head.world.x + headLength * 0.22, y: head.world.y - headLength * 0.25 }, { x: head.world.x + headLength * 0.22 + 1, y: head.world.y - headLength * 0.25 }, 5],
      ];
      const controlLayers = readObjectMap(rig, CONTROL_LAYERS_KEY);
      const generatedLayerIds = generatedLayerSet(rig);
      for (const [semantic, name, start, end, radius] of controlDescriptors) {
        const parent = semantic === 'headController' ? resolved.head : resolved.head;
        const result = ensureBone(rig, semantic, name, parent, { start, end }, semanticBones, createdBoneIds, reusedBoneIds);
        resolved[semantic] = result.id;
        ensureControlLayer(rig, semantic, result.id, `AutoRig · ${name}`, radius, controlLayers, generatedLayerIds, report);
      }
      writeObjectMap(rig, CONTROL_LAYERS_KEY, controlLayers);
      writeIdList(rig, GENERATED_LAYERS_KEY, generatedLayerIds);
    }
  }

  rig.update();
  const generated = generatedLayerSet(rig);
  if (normalized.bindArtwork) {
    const centerX = midpoint(bounds).x;
    const layerList = [...rig.layers.values()].filter(layer => !generated.has(layer.id));
    const semanticSkeleton = new Map(skeleton);
    for (const layer of layerList) {
      const layerBounds = worldBounds(rig, layer);
      const named = namedLayerMatch(layer, layerBounds, centerX);
      let match = named;
      if (match?.key === 'spineLast') match = resolved.spineLast ? { key: 'spineLast', confidence: 'name' } : undefined;
      // A semantic name is a confident request. In a partial mode, do not
      // silently attach e.g. a named head to the nearest leg just because the
      // requested head bone was intentionally omitted.
      if (!named && !match) {
        const fallback = fallbackBoneKey(rig, layer, layerBounds, semanticSkeleton, resolved);
        match = fallback ? { key: fallback, confidence: 'bounds' } : undefined;
      }
      const binding = currentBinding(rig, layer.id);
      if (binding || layer.boundBoneId) {
        const boundId = binding?.boneId ?? layer.boundBoneId;
        if (boundId && rig.bones.has(boundId)) report.boundLayerIds.push(layer.id);
        else report.unmappedLayerIds.push(layer.id);
        continue;
      }
      const targetId = match ? resolved[match.key] ?? semanticBones[match.key] : undefined;
      if (!targetId || !rig.bones.has(targetId)) {
        report.unmappedLayerIds.push(layer.id);
        report.warnings.push(`No confident bone match for artwork layer “${layer.name}”.`);
        continue;
      }
      if (rig.bind(layer.id, targetId)) {
        report.boundLayerIds.push(layer.id);
        report.newlyBoundLayerIds.push(layer.id);
      } else {
        report.unmappedLayerIds.push(layer.id);
        report.warnings.push(`Could not bind artwork layer “${layer.name}” to ${rig.bones.get(targetId)?.name ?? targetId}.`);
      }
    }
  } else {
    rig.layers.forEach(layer => {
      if (generated.has(layer.id)) return;
      const binding = currentBinding(rig, layer.id);
      if (binding || layer.boundBoneId) report.boundLayerIds.push(layer.id);
    });
  }
  report.boundLayerIds = [...new Set(report.boundLayerIds)];
  report.newlyBoundLayerIds = [...new Set(report.newlyBoundLayerIds)];
  report.unmappedLayerIds = [...new Set(report.unmappedLayerIds)];
  report.boundLayers = report.boundLayerIds;
  report.unmappedLayers = report.unmappedLayerIds;
  report.semanticBones = { ...semanticBones, ...resolved };
  report.boneCount = rig.bones.size;
  report.layerCount = rig.layers.size;
  writeObjectMap(rig, SEMANTIC_BONES_KEY, report.semanticBones);
  const serializedReport = JSON.stringify(report);
  rig.metadata['autoRig.lastMode'] = normalized.mode;
  rig.metadata['autoRig.lastSpineCount'] = String(normalized.spineCount);
  rig.metadata['autoRig.lastReport'] = serializedReport;
  rig.metadata['autoRig.mode'] = normalized.mode;
  rig.metadata['autoRig.spineCount'] = String(normalized.spineCount);
  rig.metadata['autoRig.report'] = serializedReport;
  rig.metadata.autoRigLastMode = normalized.mode;
  rig.metadata.autoRigLastSpineCount = String(normalized.spineCount);
  rig.metadata.autoRigLastReport = serializedReport;
  rig.metadata['autoRig.options'] = JSON.stringify(normalized);
  return report;
}
